entry_t *cache_get(cache_t *c, const char *key) {
    pthread_mutex_lock(&c->lock);
    entry_t *e = map_find(c, key);                  /* hsearch_r / open addressing */
    if (e) {
        lru_touch(c, e);                            /* move to MRU head: O(1) */
        entry_retain(e);                            /* eviction unlinks; release frees later */
    }
    pthread_mutex_unlock(&c->lock);
    return e;                                       /* caller must entry_release(e) */
}
/* put: lock; if (count == capacity) lru_evict_unreferenced(c); map_insert(strdup(key), value); unlock */
/* writer path after commit: cache_del(c, key) - invalidation is never automatic */
